// The emblem files the site points at (generated by scripts/gen-logo.mjs).
//
// Every failure below is silent at runtime: a 404 favicon, a header logo that renders as a
// broken-image box, a structured-data logo Google drops for being too small, or an SVG whose
// lettering falls back to a system font on someone else's machine. Caught here instead.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import sharp from 'sharp';
import { ORG_NAME, ORG_ACRONYM } from '../../scripts/lib/org-name.mjs';

const REPO = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const read = (p: string) => readFileSync(join(REPO, p), 'utf8');

// site.ts reads import.meta.env, so it cannot be imported under plain node --test: read its ORG
// literal as text instead.
const siteSrc = read('src/lib/site.ts');
const orgBlock = siteSrc.match(/export const ORG = \{[\s\S]*?\n\};/)?.[0] ?? '';
const orgField = (k: string) => {
  const m = orgBlock.match(new RegExp(`\\n  ${k}: '([^']+)',`));
  assert.ok(m, `ORG.${k} not found as a string literal in site.ts`);
  return m[1];
};

const SOURCES = [
  'src/components/Header.astro',
  'src/components/Footer.astro',
  'src/layouts/BaseLayout.astro',
];

/** Root-relative asset paths a source file references: "/brand/x.svg", "/favicon.png"… */
function referencedAssets(src: string): string[] {
  return [...src.matchAll(/(?:src|href)="(\/(?:brand\/[^"]+|favicon\.[a-z]+|logo\.png))"/g)].map((m) => m[1]);
}

test('every emblem, favicon and logo file the layout references exists', () => {
  const refs = SOURCES.flatMap((s) => referencedAssets(read(s)));
  assert.ok(
    refs.some((r) => r.startsWith('/brand/')),
    'no /brand/ asset referenced — the wiring was lost',
  );
  for (const r of refs)
    assert.ok(existsSync(join(REPO, 'public', r)), `${r} is referenced but missing from public/`);
});

test('the PNGs are square and the size their name promises', async () => {
  const expected: Record<string, number> = {
    'public/brand/ichro-emblem-512.png': 512,
    'public/brand/ichro-emblem-1024.png': 1024,
    'public/brand/ichro-apple-touch-180.png': 180,
    'public/favicon.png': 32,
    'public/logo.png': 512,
  };
  for (const [p, size] of Object.entries(expected)) {
    const m = await sharp(join(REPO, p)).metadata();
    assert.equal(m.format, 'png', `${p} is not a PNG`);
    assert.equal(m.width, size, `${p} width`);
    assert.equal(m.height, size, `${p} height`);
  }
});

test('the SVGs carry no <text> (glyphs outlined) and are titled with the official name', () => {
  const title = `The ${ORG_NAME} (${ORG_ACRONYM})`;
  for (const p of ['public/brand/ichro-emblem.svg', 'public/brand/ichro-mark.svg', 'public/favicon.svg']) {
    const svg = read(p);
    assert.doesNotMatch(svg, /<text[\s>]/, `${p} contains <text>`);
    assert.match(svg, /<title[^>]*>([^<]+)<\/title>/, `${p} has no <title>`);
    assert.equal(svg.match(/<title[^>]*>([^<]+)<\/title>/)![1], title, `${p} title`);
  }
});

test('the site name and the emblem name come from the same source', () => {
  assert.equal(orgField('name'), ORG_NAME);
  assert.equal(orgField('alternateName'), ORG_ACRONYM);
});

test('the structured-data logo is a local square PNG of at least 112px', async () => {
  const m0 = orgBlock.match(/\n {2}logo: `\$\{SITE_URL\}(\/[^`]+)`,/);
  assert.ok(m0, 'ORG.logo is not `${SITE_URL}/…` in site.ts');
  const path = m0[1];
  const file = join(REPO, 'public', path);
  assert.ok(existsSync(file), `${path} missing`);
  const m = await sharp(file).metadata();
  assert.ok((m.width ?? 0) >= 112 && m.width === m.height, `${path} is ${m.width}×${m.height}`);
});
